import std.io

pub type AppError = Failed(String)

interface Shape {
    fn area(self) -> Int64
    fn name(self) -> String { "shape" }
    fn sides(self) -> Int64
}

record Square { s: Int64 }

impl Shape for Square {
    fn area(self) -> Int64 { 4 }
    fn sides(self) -> Int64 { 5 }
}

pub fn main() effect io -> Result<(), AppError> {
    let d = Dyn<Shape>(Square { s: 1 })
    let a = d.area()
    let n = d.sides()
    io.println("${a}")
    io.println("${n}")
    return Ok(())
}
